/**
 * Seeds all scraped testimonials from the old site into Sanity.
 * Run: SANITY_WRITE_TOKEN=<token> node scripts/seed-testimonials.mjs
 *
 * Photos are downloaded from the old WordPress CDN and uploaded to Sanity assets.
 * All testimonials are set to approved=true and rated 5 stars.
 */
import { createClient } from '@sanity/client';

const client = createClient({
  projectId: 'wcccrefo',
  dataset: 'production',
  apiVersion: '2025-05-14',
  token: process.env.SANITY_WRITE_TOKEN,
  useCdn: false,
});

async function uploadFromUrl(url, filename) {
  try {
    const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const buffer = Buffer.from(await res.arrayBuffer());
    const asset = await client.assets.upload('image', buffer, { filename });
    return { _type: 'image', asset: { _type: 'reference', _ref: asset._id } };
  } catch (e) {
    console.warn(`    ⚠ Photo upload failed: ${e.message}`);
    return null;
  }
}

/** Parse "First Last, Title" → { clientName, clientTitle } */
function parseReviewer(reviewer) {
  const idx = reviewer.indexOf(',');
  if (idx === -1) return { clientName: reviewer.trim(), clientTitle: undefined };
  return {
    clientName: reviewer.slice(0, idx).trim(),
    clientTitle: reviewer.slice(idx + 1).trim() || undefined,
  };
}

