// ── Main ────────────────────────────────────────────────────────────────────

async function main() {
  if (!process.env.SANITY_WRITE_TOKEN) {
    console.error('❌ SANITY_WRITE_TOKEN env var is required');
    process.exit(1);
  }

  const total = ADVISORS.reduce((n, a) => n + a.testimonials.length, 0);
  console.log(`🚀 Seeding ${total} testimonials across ${ADVISORS.length} advisors...\n`);

  let created = 0;
  let skipped = 0;

  for (const advisor of ADVISORS) {
    console.log(`── ${advisor.slug} (${advisor.testimonials.length} testimonials)`);

    for (const [i, t] of advisor.testimonials.entries()) {
      const { clientName, clientTitle } = parseReviewer(t.reviewer);
      const docId = `testimonial-${advisor.slug}-${String(i).padStart(3, '0')}`;

      process.stdout.write(`  [${i + 1}/${advisor.testimonials.length}] ${clientName}...`);

      let photo = null;
      if (t.photo) {
        const ext = t.photo.split('?')[0].split('.').pop() ?? 'jpg';
        const filename = `${docId}.${ext}`;
        photo = await uploadFromUrl(t.photo, filename);
      }

      const doc = {
        _type: 'testimonial',
        _id: docId,
        advisorSlug: advisor.slug,
        clientName,
        ...(clientTitle && { clientTitle }),
        quote: t.text,
        rating: 5,
        ...(photo && { photo }),
        approved: true,
        submittedAt: new Date().toISOString(),
      };

      await client.createOrReplace(doc);
      created++;
      console.log(' ✓');
    }

    console.log('');
  }

  console.log(`✅ Done. ${created} created, ${skipped} skipped.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
